require_once '../includes/auth.php';require_once '../includes/functions.php';if(isTenantUser())requireTenant();global $conn;$id=(int)($_GET['id']??0);$cols=[];$q=$conn->query("SHOW COLUMNS FROM ip_pools");while($x=$q->fetch_assoc())$cols[]=$x['Field'];$has=fn($c)=>in_array($c,$cols,true);$tid=getCurrentTenantId();$sql="SELECT * FROM ip_pools WHERE id=?";$p=[$id];$t='i';if($has('tenant_id')&&$tid){$sql.=' AND tenant_id=?';$p[]=$tid;$t.='i';}$st=$conn->prepare($sql);$st->bind_param($t,...$p);$st->execute();$row=$st->get_result()->fetch_assoc();if(!$row)die('IP pool not found.');$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){requireCsrf();$map=['name'=>trim($_POST['name']??''),'network'=>trim($_POST['network']??''),'gateway'=>trim($_POST['gateway']??''),'start_ip'=>trim($_POST['start_ip']??''),'end_ip'=>trim($_POST['end_ip']??''),'status'=>$_POST['status']??'active','description'=>trim($_POST['description']??'')];$f=[];$v=[];$bt='';foreach($map as $c=>$x)if($has($c)){$f[]="$c=?";$v[]=$x;$bt.='s';}$v[]=$id;$bt.='i';$sql="UPDATE ip_pools SET ".implode(',',$f)." WHERE id=?";if($has('tenant_id')&&$tid){$sql.=' AND tenant_id=?';$v[]=$tid;$bt.='i';}$u=$conn->prepare($sql);if($u){$u->bind_param($bt,...$v);if($u->execute())redirect('index.php');$errors[]=$u->error;}}
?>
<?php require '../includes/header.php';?><div class="page-content"><div class="page-header"><div><h1>Edit IP Pool</h1></div><a class="btn btn-secondary" href="index.php">Back</a></div><?php if($errors):?><div class="alert alert-danger"><?=e(implode(' ',$errors))?></div><?php endif;?><div class="card" style="max-width:800px;padding:22px"><form method="post"><?=csrfField()?><div style="display:grid;grid-template-columns:1fr 1fr;gap:16px"><?php foreach(['name','network','gateway','start_ip','end_ip','status','description'] as $n):if(!$has($n))continue;$v=$_POST[$n]??($row[$n]??'');?><label><?=e(ucwords(str_replace('_',' ',$n)))?><?php if($n==='status'):?><select name="status"><option <?=$v==='active'?'selected':''?>>active</option><option <?=$v==='inactive'?'selected':''?>>inactive</option></select><?php else:?><input name="<?=e($n)?>" value="<?=e($v)?>"><?php endif;?></label><?php endforeach;?></div><button class="btn btn-primary" style="margin-top:18px">Update IP Pool</button></form></div></div><?php require '../includes/footer.php';?>